from research_helpers import *
a=ev('https://enercera.ngk-newvalue.com/en/products','Current five-model table reviewed. EC/ET prefixes and lowercase r preserved. ET2016C-R is current non-reflow model; under-development note refers to a future reflow-compatible type, not this exact listed model. Peak-current prose has mAh typo; not copied.')
