f=ev('https://vitrion.lpkf.com/en/company','Vitrion explicitly LPKF brand, not unrelated customer portfolio.')
ngk=[]
for name in ['EC382704P-T','EC382704P-Hr','ET382704P-H','ET2016C-R','ET1210C-H']:
 ngk.append(p('EnerCera '+name,'Rechargeable lithium-ion microbattery.',a,life='commercial',typ='product',sector='energy_storage',sub='batteries',roles=['developer','manufacturer']))
