 ngk.append(p(name,'Historical stationary sodium-sulfur battery system; manufacturer sales discontinued.',src,life='discontinued',typ='product',sector='energy_storage',sub='batteries',roles=['developer','manufacturer'],evidence=[src,b] if src!=b else [b]))
